  class InstallerEngine { private string $projectRoot; public function __construct(?string $projectRoot = null) { $this->projectRoot = $projectRoot ?? __DIR__ . '/../../../../'; } public function generateInstallerDefinition(string $productName, string $version, string $outputDir): array { if (!is_dir($outputDir)) { mkdir($outputDir, 0777, true); } $innoScript = <<<ISS ; Veltrion Framework Commercial Installer Script (Inno Setup) [Setup] AppId={{VELTRION-{$productName}-{$version}}} AppName={$productName} AppVersion={$version} AppPublisher=Veltrion Commercial Systems DefaultDirName={autopf}\\{$productName} DefaultGroupName={$productName} OutputDir={$outputDir} OutputBaseFilename={$productName}-Setup-v{$version} Compression=lzma2/max SolidCompression=yes ArchitecturesInstallIn64BitMode=x64 [Files] Source: "*"; DestDir: "{app}"; Flags: ignoreversion recursesubdirs createallsubdirs [Icons] Name: "{group}\\{$productName}"; Filename: "{app}\\launch.bat" Name: "{autodesktop}\\{$productName}"; Filename: "{app}\\launch.bat"; Tasks: desktopicon [Tasks] Name: "desktopicon"; Description: "{cm:CreateDesktopIcon}"; GroupDescription: "{cm:AdditionalIcons}"; Flags: unchecked ISS; $issPath = $outputDir . '/installer.iss'; file_put_contents($issPath, $innoScript); $manifest = [ 'product' => $productName, 'version' => $version, 'publisher' => 'Veltrion Commercial Systems', 'inno_setup_script' => $issPath, 'default_install_path' => "C:\\Program Files\\{$productName}", 'shortcuts' => ['Desktop', 'StartMenu'], 'uninstaller_generated' => true, 'timestamp' => date('Y-m-d H:i:s') ]; $manifestPath = $outputDir . '/installer-manifest.json'; file_put_contents($manifestPath, json_encode($manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)); return [ 'product' => $productName, 'version' => $version, 'inno_script' => $issPath, 'manifest' => $manifestPath ]; } } 